\begin{lemma}
\label{lemma-induction-principle-enlarge}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$. Let $W \subset X$ be a quasi-compact open
subspace. Let $P$ be a property of quasi-compact open subspaces of $X$.
Assume that
\begin{enumerate}
\item $P$ holds for $W$, and
\item for every elementary distinguished square
$(W_1 \subset W_2, f : V \to W_2)$ where 
such that
\begin{enumerate}
\item $W_1$, $W_2$ are quasi-compact open subspaces of $X$,
\item $W \subset W_1$,
\item $V$ is affine, and
\item $P$ holds for $W_1$,
\end{enumerate}
then $P$ holds for $W_2$.
\end{enumerate}
Then $P$ holds for $X$.
\end{lemma}

\begin{definition}
\label{definition-elementary-distinguished-square}
Let $S$ be a scheme. A commutative diagram
$$
\xymatrix{
U \times_W V \ar[r] \ar[d] & V \ar[d]^f \\
U \ar[r]^j & W
}
$$
of algebraic spaces over $S$ is called an {\it elementary distinguished square}
if
\begin{enumerate}
\item $U$ is an open subspace of $W$ and $j$ is the inclusion morphism,
\item $f$ is \'etale, and
\item setting $T = W \setminus U$ (with reduced induced
subspace structure) the morphism $f^{-1}(T) \to T$ is an isomorphism.
\end{enumerate}
We will indicate this by saying: ``Let $(U \subset W, f : V \to W)$
be an elementary distinguished square.''
\end{definition}

\section{Mayer-Vietoris}
\label{section-mayer-vietoris}

\noindent
In this section we prove that an elementary distinguished triangle
gives rise to various Mayer-Vietoris sequences.

\begin{definition}
\label{definition-elementary-distinguished-square}
Let $S$ be a scheme. A commutative diagram
$$
\xymatrix{
U \times_W V \ar[r] \ar[d] & V \ar[d]^f \\
U \ar[r]^j & W
}
$$
of algebraic spaces over $S$ is called an {\it elementary distinguished square}
if
\begin{enumerate}
\item $U$ is an open subspace of $W$ and $j$ is the inclusion morphism,
\item $f$ is \'etale, and
\item setting $T = W \setminus U$ (with reduced induced
subspace structure) the morphism $f^{-1}(T) \to T$ is an isomorphism.
\end{enumerate}
We will indicate this by saying: ``Let $(U \subset W, f : V \to W)$
be an elementary distinguished square.''
\end{definition}

\begin{lemma}
\label{lemma-restrict-lower-shriek}
Let $S$ be a scheme. Let $j : U \to X$ be a \'etale morphism of algebraic
spaces over $S$. Given an \'etale morphism $V \to Y$, set $W = V \times_X U$
and denote $j_W : W \to V$ the projection morphism. Then
$(j_!E)|_V = j_{W!}(E|_W)$ for $E$ in $D(\mathcal{O}_U)$.
\end{lemma}

\begin{proof}
This is true because
$(j_!\mathcal{F})|_V = j_{W!}(\mathcal{F}|_W)$
for an $\mathcal{O}_X$-module $\mathcal{F}$ as follows immediately 
from the construction of the functors $j_!$ and $j_{W!}$, see
Modules on Sites, Lemma \ref{sites-modules-lemma-extension-by-zero}.
\end{proof}

\begin{definition}
\label{definition-abelian-variety}
Let $k$ be a field. An {\it abelian variety} is a group scheme over
$k$ which is also a proper, geometrically integral variety over
$k$\footnote{For equivalent definitions see Remark \ref{remark-16-equivalent}.}.
\end{definition}

\begin{lemma}
\label{lemma-abelian-variety-smooth}
Let $k$ be a field. Let $A$ be an abelian variety over $k$.
Then $A$ is smooth over $k$.
\end{lemma}

\begin{proof}
If $k$ is perfect then this follows from
Lemma \ref{lemma-group-scheme-characteristic-zero-smooth}
(characteristic zero) and
Lemma \ref{lemma-reduced-group-scheme-prefect-field-characteristic-p-smooth}
(positive characteristic).
We can reduce the general case to this case by descent for smoothness
(Descent, Lemma \ref{descent-lemma-descending-property-smooth})
and going to the perfect closure using
Lemma \ref{lemma-abelian-variety-change-field}.
\end{proof}

\begin{definition}
\label{definition-groupoid-module}
Let $S$ be a scheme, let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
A {\it quasi-coherent module on $(U, R, s, t, c)$}
is a pair $(\mathcal{F}, \alpha)$, where $\mathcal{F}$ is a quasi-coherent
$\mathcal{O}_U$-module, and $\alpha$ is a $\mathcal{O}_R$-module
map
$$
\alpha : t^*\mathcal{F} \longrightarrow s^*\mathcal{F}
$$
such that
\begin{enumerate}
\item the diagram
$$
\xymatrix{
& \text{pr}_1^*t^*\mathcal{F} \ar[r]_-{\text{pr}_1^*\alpha} &
\text{pr}_1^*s^*\mathcal{F} \ar@{=}[rd] & \\
\text{pr}_0^*s^*\mathcal{F} \ar@{=}[ru] & & & c^*s^*\mathcal{F} \\
& \text{pr}_0^*t^*\mathcal{F} \ar[lu]^{\text{pr}_0^*\alpha} \ar@{=}[r] &
c^*t^*\mathcal{F} \ar[ru]_{c^*\alpha}
}
$$
is a commutative in the category of
$\mathcal{O}_{R \times_{s, U, t} R}$-modules, and
\item the pullback
$$
e^*\alpha : \mathcal{F} \longrightarrow \mathcal{F}
$$
is the identity map.
\end{enumerate}
Compare with the commutative diagrams of Lemma \ref{lemma-diagram}.
\end{definition}

\noindent
The commutativity of the first diagram forces the operator $e^*\alpha$
to be idempotent. Hence the second condition can be reformulated as saying
that $e^*\alpha$ is an isomorphism. In fact, the condition implies that
$\alpha$ is an isomorphism.

\begin{lemma}
\label{lemma-isomorphism}
Let $S$ be a scheme, let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
If $(\mathcal{F}, \alpha)$ is a quasi-coherent module on $(U, R, s, t, c)$
then $\alpha$ is an isomorphism.
\end{lemma}

\begin{proof}
Pull back the commutative diagram of
Definition \ref{definition-groupoid-module}
by the morphism $(i, 1) : R \to R \times_{s, U, t} R$.
Then we see that $i^*\alpha \circ \alpha = s^*e^*\alpha$.
Pulling back by the morphism $(1, i)$ we obtain the relation
$\alpha \circ i^*\alpha = t^*e^*\alpha$. By the second assumption 
these morphisms are the identity. Hence $i^*\alpha$ is an inverse of
$\alpha$.
\end{proof}

\begin{definition}
\label{definition-groupoid-module}
Let $S$ be a scheme, let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
